#include <iostream>
#include <queue>
#include <string>
#include <vector>
struct Task { int priority; std::string name; };
struct LowerPriorityFirst { bool operator()(const Task& a, const Task& b) const { return a.priority < b.priority; } };
int main() {
    std::priority_queue<Task, std::vector<Task>, LowerPriorityFirst> tasks;
    tasks.push({1, "docs"}); tasks.push({5, "backup"}); tasks.push({3, "report"});
    std::cout << tasks.top().name << ':' << tasks.top().priority << '\n';
}
